buildGradleAdditions.insert:
repositories {
    google()
    mavenCentral()
    maven { url 'https://cboost.jfrog.io/artifactory/chartboost-ads/' }
}
dependencies {
    implementation('com.google.ads.mediation:chartboost') {
        version {
            strictly '9.13.0.0'
        }
    }
}

gameActivityClassAdditions.insert:
public boolean AndroidThunkJava_ApplyOpenMobileAdsAdMobChartboostConsentSignals(
    final boolean applyGdpr,
    final boolean hasUserConsent,
    final boolean applyUsPrivacy,
    final boolean doNotSell
)
{
    try
    {
        if (applyGdpr)
        {
            com.chartboost.sdk.privacy.model.GDPR consent =
                new com.chartboost.sdk.privacy.model.GDPR(
                    hasUserConsent
                        ? com.chartboost.sdk.privacy.model.GDPR.GDPR_CONSENT.BEHAVIORAL
                        : com.chartboost.sdk.privacy.model.GDPR.GDPR_CONSENT.NON_BEHAVIORAL
                );
            com.chartboost.sdk.Chartboost.addDataUseConsent(GameActivity.this, consent);
            com.chartboost.sdk.privacy.model.DataUseConsent applied =
                com.chartboost.sdk.Chartboost.getDataUseConsent(
                    GameActivity.this,
                    com.chartboost.sdk.privacy.model.GDPR.GDPR_STANDARD
                );
            if (!(applied instanceof com.chartboost.sdk.privacy.model.GDPR)
                || !((com.chartboost.sdk.privacy.model.GDPR) applied).getConsent()
                    .equals(consent.getConsent()))
            {
                return false;
            }
        }
        if (applyUsPrivacy)
        {
            com.chartboost.sdk.privacy.model.CCPA consent =
                new com.chartboost.sdk.privacy.model.CCPA(
                    doNotSell
                        ? com.chartboost.sdk.privacy.model.CCPA.CCPA_CONSENT.OPT_OUT_SALE
                        : com.chartboost.sdk.privacy.model.CCPA.CCPA_CONSENT.OPT_IN_SALE
                );
            com.chartboost.sdk.Chartboost.addDataUseConsent(GameActivity.this, consent);
            com.chartboost.sdk.privacy.model.DataUseConsent applied =
                com.chartboost.sdk.Chartboost.getDataUseConsent(
                    GameActivity.this,
                    com.chartboost.sdk.privacy.model.CCPA.CCPA_STANDARD
                );
            if (!(applied instanceof com.chartboost.sdk.privacy.model.CCPA)
                || !((com.chartboost.sdk.privacy.model.CCPA) applied).getConsent()
                    .equals(consent.getConsent()))
            {
                return false;
            }
        }
        return true;
    }
    catch (Exception exception)
    {
        return false;
    }
}
